WHEN 'constraint' THEN (SELECT jsonb_build_object('definition',pg_get_constraintdef(oid)) FROM pg_constraint WHERE conrelid=to_regclass((i->>'schema')||'.'||(i->>'table')) AND conname=i->>'name')
WHEN 'table' THEN (SELECT jsonb_build_object('owner',pg_get_userbyid(relowner),'acl',relacl::text,'rls',relrowsecurity,'force_rls',relforcerowsecurity) FROM pg_class WHERE oid=to_regclass((i->>'schema')||'.'||(i->>'table')))
WHEN 'index' THEN (SELECT jsonb_build_object('indexdef',indexdef) FROM pg_indexes WHERE schemaname=i->>'schemaname' AND indexname=i->>'indexname')
END actual FROM e),
checkrows AS (SELECT kind,COALESCE(i->>'schema',i->>'schemaname') schema,COALESCE(i->>'name',i->>'indexname',i->>'table') name,
actual,CASE kind WHEN 'column' THEN i-'name'-'table'-'schema'-'data_type' WHEN 'constraint' THEN jsonb_build_object('definition',i->'definition') WHEN 'table' THEN i-'schema'-'table' WHEN 'index' THEN jsonb_build_object('indexdef',i->'indexdef') END expected FROM a)
